// The shape of react-hook-form's `Path<T>`: every property name and dotted property path of `T`.
export type Path<T> = {
  [K in keyof T & string]: T[K] extends readonly unknown[]
    ? K
    : T[K] extends object
      ? K | `${K}.${Path<T[K]>}`
      : K;
}[keyof T & string];
export declare function setError<T>(name: Path<T>, error: { type: string }): void;
